import {
  LayoutDashboard,
  FolderSearch,
  ClipboardList,
  Package,
  ClipboardCheck,
  Lock,
  Award,
  BadgeCheck,
  FileText,
  Map,
  BarChart3,
  TrendingUp,
  User,
  Users,
  Wrench,
  Settings,
  HelpCircle,
  Rocket,
  Bot,
  Info,
  ChevronDown,
  Github,
  BookOpen,
  Download,
  Building2,
  Server,
  Mail,
  Activity,
  ShieldCheck,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { usePrefetch } from '@/hooks/usePrefetch';
import { usePermissions } from '@/hooks/usePermissions';

interface SidebarProps {
  currentView: string;
  onNavigate: (view: string) => void;
  isOpen: boolean;
  onClose: () => void;
  isAdmin?: boolean;
  isAuthenticated?: boolean;
}

interface NavItem {
  view: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  permission?: string;
}

interface NavGroup {
  label: string;
  items: NavItem[];
}

const navGroups: NavGroup[] = [
  {
    label: 'Scan',
    items: [
      { view: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
      { view: 'analyze', label: 'Analyze', icon: FolderSearch, permission: 'write:scans' },
      { view: 'results', label: 'Results', icon: ClipboardList, permission: 'read:all' },
      { view: 'repository-health', label: 'Repo Health', icon: Package, permission: 'read:all' },
    ],
  },
  {
    label: 'Compliance',
    items: [
      { view: 'audit', label: 'Audit Report', icon: ClipboardCheck, permission: 'read:audit' },
      { view: 'security', label: 'Security', icon: Lock, permission: 'read:all' },
      { view: 'security-admin', label: 'Security Ops', icon: ShieldCheck, permission: 'admin:all' },
      { view: 'quality', label: 'Quality', icon: Award, permission: 'read:all' },
      { view: 'trust', label: 'Trust', icon: BadgeCheck, permission: 'read:all' },
    ],
  },
  {
    label: 'Operations',
    items: [
      { view: 'assessments', label: 'Assessments', icon: FileText, permission: 'read:all' },
      { view: 'remediation', label: 'Remediation', icon: Map, permission: 'read:all' },
      { view: 'platform', label: 'Platform', icon: BarChart3, permission: 'read:analytics' },
      { view: 'analytics-dashboard', label: 'Audit Analytics', icon: Activity, permission: 'read:analytics' },
      { view: 'team-metrics', label: 'Team Metrics', icon: TrendingUp, permission: 'read:analytics' },
      { view: 'outreach-analytics', label: 'Outreach Analytics', icon: Mail, permission: 'read:analytics' },
      { view: 'organization', label: 'Organization', icon: Building2, permission: 'admin:all' },
      { view: 'enterprise', label: 'Enterprise', icon: Server, permission: 'admin:all' },
      { view: 'profile', label: 'Profile', icon: User },
      { view: 'admin', label: 'Admin', icon: Users, permission: 'admin:all' },
    ],
  },
  {
    label: 'System',
    items: [
      { view: 'tools', label: 'Tools', icon: Wrench, permission: 'write:all' },
      { view: 'settings', label: 'Settings', icon: Settings, permission: 'admin:all' },
      { view: 'help', label: 'Help', icon: HelpCircle },
      { view: 'getting-started', label: 'Getting Started', icon: Rocket },
      { view: 'chatbot', label: 'Chatbot', icon: Bot },
      { view: 'about', label: 'About', icon: Info },
    ],
  },
];

// Views that require authentication — hidden from sidebar when signed out
const AUTH_REQUIRED_VIEWS = new Set(['admin', 'organization', 'profile', 'chatbot']);

export function Sidebar({
  currentView,
  onNavigate,
  isOpen,
  onClose,
  isAdmin,
  isAuthenticated,
}: SidebarProps) {
  const { prefetchOnHover } = usePrefetch(currentView);
  const { hasPermission, loading: permsLoading } = usePermissions(!!isAuthenticated);
  return (
    <>
      {isOpen && <div className="fixed inset-0 z-40 bg-black/50 lg:hidden" onClick={onClose} />}
      <aside
        className={cn(
          'fixed inset-y-0 left-0 z-50 flex w-56 flex-col border-r border-border bg-card transition-transform lg:static lg:translate-x-0',
          isOpen ? 'translate-x-0' : '-translate-x-full'
        )}
      >
        <div className="flex h-14 items-center gap-2 border-b border-border px-4">
          <div className="flex items-center gap-2">
            <div className="flex h-8 w-8 items-center justify-center rounded-md bg-primary">
              <svg
                viewBox="0 0 24 24"
                className="h-5 w-5 text-primary-foreground"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
              >
                <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
                <polyline points="9 12 12 15 16 10" />
              </svg>
            </div>
            <span className="text-sm font-bold tracking-tight">SimpleBeacon</span>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto scrollbar-thin px-2 py-3 overscroll-contain">
          {navGroups.map((group) => (
            <NavGroupSection
              key={group.label}
              group={group}
              currentView={currentView}
              onNavigate={onNavigate}
              isAdmin={!!isAdmin}
              isAuthenticated={!!isAuthenticated}
              onHover={prefetchOnHover}
              hasPermission={hasPermission}
              permsLoading={permsLoading}
            />
          ))}
        </nav>

        <div className="flex items-center gap-1 border-t border-border px-3 py-2">
          <a
            href="https://github.com/tjp420/simplebeacon"
            target="_blank"
            rel="noopener noreferrer"
            className="flex h-8 w-8 items-center justify-center rounded-md text-foreground-muted hover:bg-muted hover:text-foreground"
            title="GitHub"
          >
            <Github className="h-4 w-4" />
          </a>
          <a
            href="https://github.com/tjp420/simplebeacon/blob/main/docs/ANTI-BLOAT-MANIFESTO.md"
            target="_blank"
            rel="noopener noreferrer"
            className="flex h-8 w-8 items-center justify-center rounded-md text-foreground-muted hover:bg-muted hover:text-foreground"
            title="Docs"
          >
            <BookOpen className="h-4 w-4" />
          </a>
          <button
            type="button"
            onClick={async () => {
              try {
                const res = await fetch('/api/simplebeacon/report');
                if (!res.ok) return;
                const data = await res.json();
                const blob = new Blob([JSON.stringify(data, null, 2)], {
                  type: 'application/json',
                });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'simplebeacon-report.json';
                a.click();
                URL.revokeObjectURL(url);
              } catch {
                /* ignore download errors */
              }
            }}
            className="flex h-8 w-8 items-center justify-center rounded-md text-foreground-muted hover:bg-muted hover:text-foreground"
            title="Export Report"
          >
            <Download className="h-4 w-4" />
          </button>
        </div>
      </aside>
    </>
  );
}

function NavGroupSection({
  group,
  currentView,
  onNavigate,
  isAdmin,
  isAuthenticated,
  onHover,
  hasPermission,
  permsLoading,
}: {
  group: NavGroup;
  currentView: string;
  onNavigate: (v: string) => void;
  isAdmin: boolean;
  isAuthenticated: boolean;
  onHover: (view: string) => void;
  hasPermission: (perm: string) => boolean;
  permsLoading: boolean;
}) {
  return (
    <div className="mb-2">
      <div className="flex items-center gap-1 px-2 py-1.5 text-xs font-semibold uppercase tracking-wider text-foreground-muted">
        <ChevronDown className="h-3 w-3" />
        <span>{group.label}</span>
      </div>
      <div className="space-y-0.5">
        {group.items
          .filter((item) => {
            // Hide admin-only items from non-admin users
            if (!isAdmin && item.view === 'admin') return false;
            // Hide auth-required items from signed-out users
            if (!isAuthenticated && AUTH_REQUIRED_VIEWS.has(item.view)) return false;
            // Hide items requiring permissions the user doesn't have
            if (item.permission && !permsLoading && !hasPermission(item.permission)) return false;
            return true;
          })
          .map((item) => {
            const Icon = item.icon;
            const isActive = currentView === item.view;
            return (
              <button
                key={item.view}
                type="button"
                onClick={() => onNavigate(item.view)}
                onMouseEnter={() => onHover(item.view)}
                onFocus={() => onHover(item.view)}
                className={cn(
                  'flex w-full items-center gap-2.5 rounded-md px-2 py-1.5 text-sm font-medium transition-colors',
                  isActive
                    ? 'bg-primary-subtle text-primary'
                    : 'text-foreground-secondary hover:bg-muted hover:text-foreground'
                )}
              >
                <Icon className="h-4 w-4 shrink-0" />
                <span>{item.label}</span>
              </button>
            );
          })}
      </div>
    </div>
  );
}
